#!/usr/bin/env python3
"""Calculate mean temperatures for the stations in the sample climate data."""

from configparser import ConfigParser
from pathlib import Path

import pandas as pd


BASE_DIR = Path(__file__).resolve().parent
DATA_PATH = BASE_DIR / "climate_analyzer" / "sample_data" / "climate_data.csv"
CONFIG_PATH = BASE_DIR / "climate_analyzer" / "config.ini"


def read_config(config_path: Path) -> ConfigParser:
    """Read the UTF-8 configuration file using Python 3's configparser."""
    config = ConfigParser()
    config.read(config_path, encoding="utf-8")
    return config


def load_temperature_data(data_path: Path) -> pd.DataFrame:
    """Load the climate data from a UTF-8 CSV file."""
    return pd.read_csv(data_path, encoding="utf-8")


def mean_temperatures(data: pd.DataFrame) -> pd.Series:
    """Return the mean temperature for each station in the data."""
    return data.groupby("station_id")["temperature"].mean()


def main() -> None:
    read_config(CONFIG_PATH)
    data = load_temperature_data(DATA_PATH)

    for station_id, mean_temperature in mean_temperatures(data).items():
        print(f"Station {station_id} mean temperature: {mean_temperature:.1f}°C")


if __name__ == "__main__":
    main()
